import{bV as t,aL as r,u as e,G as o}from"./chunks/framework.BfzMay2U.js";const u=JSON.parse('{"title":"制造业 PHP 面试题：测试、上线与需求协作（126—150）","description":"","frontmatter":{"title":"制造业 PHP 面试题：测试、上线与需求协作（126—150）","date":"2026-11-15T10:50:00.000Z","categories":["面试","PHP"],"tags":["测试","软件验证","上线运维","需求分析","文档","故障排查"],"sidebarSort":6},"headers":[],"relativePath":"php/jd/delivery-troubleshooting-interview.md","filePath":"php/jd/delivery-troubleshooting-interview.md"}'),n={name:"php/jd/delivery-troubleshooting-interview.md"};function s(h,a,i,l,d,p){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="制造业-php-面试题-测试、上线与需求协作-126—150" tabindex="-1">制造业 PHP 面试题：测试、上线与需求协作（126—150） <a class="header-anchor" href="#制造业-php-面试题-测试、上线与需求协作-126—150" aria-label="Permalink to &quot;制造业 PHP 面试题：测试、上线与需求协作（126—150）&quot;">​</a></h1><p>本篇对应 JD 中“独立交付、异常排查、需求转化、测试验证、受控发布与文档沉淀”。场景回答建议采用“事实与影响 → 定位证据 → 处理动作 → 验证及后续改进”的顺序。</p><h2 id="一、测试验证与交付证据" tabindex="-1">一、测试验证与交付证据 <a class="header-anchor" href="#一、测试验证与交付证据" aria-label="Permalink to &quot;一、测试验证与交付证据&quot;">​</a></h2><h3 id="_126-单元测试、集成测试、端到端测试和-uat-有何区别" tabindex="-1">126. 单元测试、集成测试、端到端测试和 UAT 有何区别？ <a class="header-anchor" href="#_126-单元测试、集成测试、端到端测试和-uat-有何区别" aria-label="Permalink to &quot;126. 单元测试、集成测试、端到端测试和 UAT 有何区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 单元测试验证局部业务规则，集成测试验证数据库、接口与组件协作，端到端测试验证用户关键流程，UAT 由业务按真实场景确认是否满足使用目标。它们覆盖不同风险，不能用一项通过替代其他必要验证。</p><p><strong>追问要点：</strong> 不必追求所有代码同样多测试，应优先覆盖扣料、权限、状态、审计和接口异常等高影响规则。</p><h3 id="_127-如何为一个报工功能制定完整测试矩阵" tabindex="-1">127. 如何为一个报工功能制定完整测试矩阵？ <a class="header-anchor" href="#_127-如何为一个报工功能制定完整测试矩阵" aria-label="Permalink to &quot;127. 如何为一个报工功能制定完整测试矩阵？&quot;">​</a></h3><p><strong>参考回答：</strong> 从角色、工厂、状态、数量边界、工序前置、物料、质量和网络故障等维度选择有意义的组合。覆盖正常、重复、同键冲突、越权、并发超量、库存不足、事务失败和外部超时，同时核对数据库副作用与审计结果。</p><p><strong>追问要点：</strong> “全场景”不是穷举无限组合，应记录风险与覆盖依据，保留关键边界、异常和现实操作路径的测试证据。</p><h3 id="_128-怎么验证-两个请求同时提交也只扣一次料" tabindex="-1">128. 怎么验证“两个请求同时提交也只扣一次料”？ <a class="header-anchor" href="#_128-怎么验证-两个请求同时提交也只扣一次料" aria-label="Permalink to &quot;128. 怎么验证“两个请求同时提交也只扣一次料”？&quot;">​</a></h3><p><strong>参考回答：</strong> 使用真实 MySQL 和两个独立请求或连接，在接近同一时刻提交同一个幂等键，再查询报工、消耗和库存流水，确认只形成一次业务效果。另用两个不同键争抢不足以同时满足的库存，验证至少一方被拒绝且库存不为负。</p><p><strong>追问要点：</strong> 在同一数据库连接顺序调用两次不是并发测试；仅检查 HTTP 成功次数也不能证明库存正确。</p><h3 id="_129-第三方接口无法随时调用-怎样测试" tabindex="-1">129. 第三方接口无法随时调用，怎样测试？ <a class="header-anchor" href="#_129-第三方接口无法随时调用-怎样测试" aria-label="Permalink to &quot;129. 第三方接口无法随时调用，怎样测试？&quot;">​</a></h3><p><strong>参考回答：</strong> 在本地通过框架 Fake 或既有客户端边界模拟成功、超时、错误码、响应缺字段、重复和状态未知，验证本地决策。联调环境再用供应商沙箱或批准样例核对签名、字段及真实业务状态，保留契约与版本。</p><p><strong>追问要点：</strong> Mock 只证明代码按假设工作，不能证明假设与供应商一致。接口契约变化应触发回归。</p><h3 id="_130-uat-发现的问题与需求变更如何区分" tabindex="-1">130. UAT 发现的问题与需求变更如何区分？ <a class="header-anchor" href="#_130-uat-发现的问题与需求变更如何区分" aria-label="Permalink to &quot;130. UAT 发现的问题与需求变更如何区分？&quot;">​</a></h3><p><strong>参考回答：</strong> 对照已确认的验收规则和样例，不满足约定的是缺陷，新增规则或改变目标可能是需求变更。若原规则含糊，先确认业务目标和影响，记录共同决议，再评估修改、回归和上线安排，避免只凭开发者个人解释。</p><p><strong>追问要点：</strong> 重要质量风险不能因为文档没写就忽略，应提出影响并交由相应责任人决定控制措施。</p><h3 id="_131-软件测试和软件验证是一回事吗" tabindex="-1">131. 软件测试和软件验证是一回事吗？ <a class="header-anchor" href="#_131-软件测试和软件验证是一回事吗" aria-label="Permalink to &quot;131. 软件测试和软件验证是一回事吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 测试提供某些条件下行为的证据，验证还需证明软件适合既定用途，通常结合需求、风险、设计、测试、缺陷关闭和运行控制。医疗制造系统的具体过程与交付物由质量体系和适用要求确定，开发负责提供可追踪的技术证据。</p><p><strong>追问要点：</strong> 不把“用例全部通过”或“测试覆盖率高”直接等同于适用性和合规性结论。</p><h3 id="_132-需求追踪矩阵怎么做才有用" tabindex="-1">132. 需求追踪矩阵怎么做才有用？ <a class="header-anchor" href="#_132-需求追踪矩阵怎么做才有用" aria-label="Permalink to &quot;132. 需求追踪矩阵怎么做才有用？&quot;">​</a></h3><p><strong>参考回答：</strong> 将需求编号关联到风险、控制措施、实现版本、测试用例与结果，缺陷修复后补复测证据。例如“重复报工不得重复扣料”关联唯一约束、事务设计、并发用例和库存核对结果。矩阵用于找遗漏及评估变更影响。</p><p><strong>追问要点：</strong> 不必为小改动堆大量文档，但关键控制要能找到证据；需求删除、规则变更也要更新关联，不只在首次上线填写。</p><h3 id="_133-权限和审计应该测试哪些负向场景" tabindex="-1">133. 权限和审计应该测试哪些负向场景？ <a class="header-anchor" href="#_133-权限和审计应该测试哪些负向场景" aria-label="Permalink to &quot;133. 权限和审计应该测试哪些负向场景？&quot;">​</a></h3><p><strong>参考回答：</strong> 验证未登录、已停用、越工厂、低权限调用高权限接口、改 URL 读取附件、批量导出越权、创建人自审和任务执行时权限变化。审计检查成功动作、规定需要记录的失败尝试、前后值、原因及敏感字段处理。</p><p><strong>追问要点：</strong> 拒绝动作不能留下半条业务写入；审计写入失败时是否阻断业务要由记录重要性与设计要求明确。</p><h2 id="二、发布、监控与故障处理" tabindex="-1">二、发布、监控与故障处理 <a class="header-anchor" href="#二、发布、监控与故障处理" aria-label="Permalink to &quot;二、发布、监控与故障处理&quot;">​</a></h2><h3 id="_134-一个受控发布清单最少包含什么" tabindex="-1">134. 一个受控发布清单最少包含什么？ <a class="header-anchor" href="#_134-一个受控发布清单最少包含什么" aria-label="Permalink to &quot;134. 一个受控发布清单最少包含什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 变更范围、版本与构建产物、测试和缺陷状态、数据库脚本、配置与密钥引用、依赖系统、备份、执行人、批准记录、窗口、验证步骤及回退条件。按团队实际流程控制，生产操作使用最小权限并记录结果。</p><p><strong>追问要点：</strong> 版本号要能对应具体代码和配置，不能现场手工改一份无人知道来源的文件后宣称发布完成。</p><h3 id="_135-laravel-更新代码后-为什么后台任务还跑旧逻辑" tabindex="-1">135. Laravel 更新代码后，为什么后台任务还跑旧逻辑？ <a class="header-anchor" href="#_135-laravel-更新代码后-为什么后台任务还跑旧逻辑" aria-label="Permalink to &quot;135. Laravel 更新代码后，为什么后台任务还跑旧逻辑？&quot;">​</a></h3><p><strong>参考回答：</strong> 队列 worker 是长驻进程，可能仍持有旧代码；还可能存在旧容器、配置或路由缓存未更新。发布时按部署方式重新加载进程与缓存，确保当前任务和新任务的切换受控，并监控 worker 是否实际完成切换。</p><p><strong>追问要点：</strong> 不能直接强杀所有长任务而不考虑重投；新旧 Job 数据结构要兼容仍在队列中的历史消息。</p><h3 id="_136-回滚代码为什么不等于回滚系统" tabindex="-1">136. 回滚代码为什么不等于回滚系统？ <a class="header-anchor" href="#_136-回滚代码为什么不等于回滚系统" aria-label="Permalink to &quot;136. 回滚代码为什么不等于回滚系统？&quot;">​</a></h3><p><strong>参考回答：</strong> 数据库结构与数据、已发出的 ERP 请求、文件和消息不会随代码自动回到过去。回退方案必须区分应用回退、数据修复、功能关闭和业务补偿，优先采用兼容的数据库变更，明确不可逆动作。</p><p><strong>追问要点：</strong> 已新增且被使用的字段不能直接删除；已入库的真实业务单据通常要受控冲销，不能恢复旧库覆盖后续合法数据。</p><h3 id="_137-上线后应该监控哪些指标" tabindex="-1">137. 上线后应该监控哪些指标？ <a class="header-anchor" href="#_137-上线后应该监控哪些指标" aria-label="Permalink to &quot;137. 上线后应该监控哪些指标？&quot;">​</a></h3><p><strong>参考回答：</strong> 监控请求错误率与延迟分位数、FPM 与应用容量、数据库连接和锁等待、队列积压年龄、同步成功与未知状态、设备心跳、对账差异，以及关键业务量。为高影响问题设置可执行的告警入口和责任人。</p><p><strong>追问要点：</strong> 平均耗时掩盖慢请求，应关注 p95、p99 等分位数；阈值根据业务窗口和容量基线确定，不随意给所有系统套同一数字。</p><h3 id="_138-用户说-报工点了没反应-怎样排查" tabindex="-1">138. 用户说“报工点了没反应”，怎样排查？ <a class="header-anchor" href="#_138-用户说-报工点了没反应-怎样排查" aria-label="Permalink to &quot;138. 用户说“报工点了没反应”，怎样排查？&quot;">​</a></h3><p><strong>参考回答：</strong> 先收集时间、账号、工单、终端与请求 ID，检查本地是否待同步、请求是否发出、后端是否接收及最终状态。沿网关、Laravel、SQL、队列和 ERP 查耗时与错误，再用业务键确认是否已经成功，避免引导重复提交。</p><p><strong>追问要点：</strong> 若操作已成功而页面超时，应修正反馈或补充结果查询；若确未接收，再按原键安全重试，不能直接新建报工记录。</p><h3 id="_139-队列突然大量积压-你会怎么办" tabindex="-1">139. 队列突然大量积压，你会怎么办？ <a class="header-anchor" href="#_139-队列突然大量积压-你会怎么办" aria-label="Permalink to &quot;139. 队列突然大量积压，你会怎么办？&quot;">​</a></h3><p><strong>参考回答：</strong> 比较进入速率、消费速率、最老任务年龄和失败类型，检查 worker、数据库、外部接口、限流及重试风暴。先保护生产关键链路，暂停低优先级任务或故障依赖的无效重试，再按瓶颈和下游容量恢复消费。</p><p><strong>追问要点：</strong> 增加 worker 可能扩大数据库锁竞争或把供应商打挂。恢复后验证重复消费、死信、业务延迟和对账，而不是只看队列长度归零。</p><h3 id="_140-生产数据错了-业务要求你立刻改库-怎么处理" tabindex="-1">140. 生产数据错了，业务要求你立刻改库，怎么处理？ <a class="header-anchor" href="#_140-生产数据错了-业务要求你立刻改库-怎么处理" aria-label="Permalink to &quot;140. 生产数据错了，业务要求你立刻改库，怎么处理？&quot;">​</a></h3><p><strong>参考回答：</strong> 先确认影响、权威来源、原始证据和业务恢复目标，优先走已有受控更正或冲销接口。确需数据修复时，按批准流程制定限定范围脚本、前置校验、备份、事务和核对方案，在适当环境演练，执行后留证并对账。</p><p><strong>追问要点：</strong> 不直接删日志掩盖错误，不用无限制 <code>UPDATE</code>。涉及签名记录和下游单据时，必须同步评估更正、复核与补偿。</p><h3 id="_141-故障复盘怎样避免变成-以后注意" tabindex="-1">141. 故障复盘怎样避免变成“以后注意”？ <a class="header-anchor" href="#_141-故障复盘怎样避免变成-以后注意" aria-label="Permalink to &quot;141. 故障复盘怎样避免变成“以后注意”？&quot;">​</a></h3><p><strong>参考回答：</strong> 记录影响范围、时间线、触发条件、发现和恢复过程，以日志和数据解释根因及促成因素。改进项落到具体负责人、期限和验证方法，例如补充唯一约束、增加未知状态查询和演练恢复，而不是只要求个人更仔细。</p><p><strong>追问要点：</strong> 区分立即止血和长期修复，检查改进是否生效；不要把“重启后好了”当成根因。</p><h2 id="三、需求转化、文档与面试表达" tabindex="-1">三、需求转化、文档与面试表达 <a class="header-anchor" href="#三、需求转化、文档与面试表达" aria-label="Permalink to &quot;三、需求转化、文档与面试表达&quot;">​</a></h2><h3 id="_142-业务说-加一个生产报表-你需要问什么" tabindex="-1">142. 业务说“加一个生产报表”，你需要问什么？ <a class="header-anchor" href="#_142-业务说-加一个生产报表-你需要问什么" aria-label="Permalink to &quot;142. 业务说“加一个生产报表”，你需要问什么？&quot;">​</a></h3><p><strong>参考回答：</strong> 确认使用人、决策目的、统计对象、口径、时间与班次、维度、筛选、刷新频率、权限、导出格式及最大数据量。让业务提供一份小样本和手工计算结果，再形成可验收定义。</p><p><strong>追问要点：</strong> “按车间统计良率”还需明确返工、跨班次、报废和零分母，不应直接开始写 <code>GROUP BY</code>。</p><h3 id="_143-模糊或冲突的业务规则如何结构化" tabindex="-1">143. 模糊或冲突的业务规则如何结构化？ <a class="header-anchor" href="#_143-模糊或冲突的业务规则如何结构化" aria-label="Permalink to &quot;143. 模糊或冲突的业务规则如何结构化？&quot;">​</a></h3><p><strong>参考回答：</strong> 用规则表写出条件、输入、允许动作、结果、优先级和异常，并列举冲突样例。例如“生产经理可补录”与“关闭工单禁止修改”冲突时，明确是否需要重开、审批或独立更正。由对应业务责任人确认决议后版本化。</p><p><strong>追问要点：</strong> 将事实、假设、待决项和风险分开记录；开发人员可以提出取舍建议，但不能无记录地替质量负责人决定放行规则。</p><h3 id="_144-怎样把需求拆成可以开发和验收的任务" tabindex="-1">144. 怎样把需求拆成可以开发和验收的任务？ <a class="header-anchor" href="#_144-怎样把需求拆成可以开发和验收的任务" aria-label="Permalink to &quot;144. 怎样把需求拆成可以开发和验收的任务？&quot;">​</a></h3><p><strong>参考回答：</strong> 按可交付业务动作拆分，并列数据结构、页面、接口、规则、权限、状态、审计、异常、测试和上线项。识别依赖与风险，先验证关键接口或数据规则，再完成端到端闭环，避免只按“前端、后端各一项”粗分。</p><p><strong>追问要点：</strong> 任务完成标准应是可演示的行为和证据，例如“同键重试返回原报工号且不再扣料”，而不是“代码写完”。</p><h3 id="_145-排期紧又有新需求插入-你怎样沟通" tabindex="-1">145. 排期紧又有新需求插入，你怎样沟通？ <a class="header-anchor" href="#_145-排期紧又有新需求插入-你怎样沟通" aria-label="Permalink to &quot;145. 排期紧又有新需求插入，你怎样沟通？&quot;">​</a></h3><p><strong>参考回答：</strong> 用当前范围、完成情况、依赖和风险说明影响，给出缩减非核心范围、调整顺序或延后日期等具体选择。确认优先级后更新验收和上线计划，对扣料正确性、权限及必要验证不因赶工直接省略。</p><p><strong>追问要点：</strong> 不把所有内容都标成最高优先级，也不凭感觉承诺日期；对未确认的供应商联调时间单独说明依赖。</p><h3 id="_146-多部门与供应商协作-如何推动问题闭环" tabindex="-1">146. 多部门与供应商协作，如何推动问题闭环？ <a class="header-anchor" href="#_146-多部门与供应商协作-如何推动问题闭环" aria-label="Permalink to &quot;146. 多部门与供应商协作，如何推动问题闭环？&quot;">​</a></h3><p><strong>参考回答：</strong> 一条问题记录包含业务影响、复现条件、关联编号、证据、当前定位、责任人、下一步和完成期限。定期跟进阻塞，必要时按影响升级；修复后由约定人员复测确认，关联版本和上线记录后关闭。</p><p><strong>追问要点：</strong> “已转发给供应商”不等于解决；开发可以推动技术定位，但业务规则和现场操作仍要由相应部门共同确认。</p><h3 id="_147-技术文档怎样写才方便接手" tabindex="-1">147. 技术文档怎样写才方便接手？ <a class="header-anchor" href="#_147-技术文档怎样写才方便接手" aria-label="Permalink to &quot;147. 技术文档怎样写才方便接手？&quot;">​</a></h3><p><strong>参考回答：</strong> 开发说明描述模块边界、数据模型和关键规则，接口文档描述契约与异常，部署文档给出前置条件、步骤、验证和回退，测试记录保留用例、环境、结果及缺陷，版本记录说明行为变化及迁移影响。文件要与代码版本关联并及时更新。</p><p><strong>追问要点：</strong> 密钥使用受控引用，不能贴进文档；常见故障说明要给诊断依据和处理边界，不能只写“有问题重启”。</p><h3 id="_148-哪些东西值得沉淀成组件-哪些不值得" tabindex="-1">148. 哪些东西值得沉淀成组件，哪些不值得？ <a class="header-anchor" href="#_148-哪些东西值得沉淀成组件-哪些不值得" aria-label="Permalink to &quot;148. 哪些东西值得沉淀成组件，哪些不值得？&quot;">​</a></h3><p><strong>参考回答：</strong> 已被重复验证的通用能力，例如统一请求、错误分类、字段校验和标准日志上下文，适合按现有结构复用；尚未稳定的业务差异先保留明确实现。是否抽取看重复成本、变化方向和边界清晰度，不能按代码行数决定。</p><p><strong>追问要点：</strong> 不把不同 ERP 的业务拒绝都合成一种异常，也不为了抽取公共流程丢失某个工厂特有的质量校验。</p><h3 id="_149-没有-mes、e-dhr-或-uniapp-实战经验-如何回答" tabindex="-1">149. 没有 MES、E-DHR 或 UniApp 实战经验，如何回答？ <a class="header-anchor" href="#_149-没有-mes、e-dhr-或-uniapp-实战经验-如何回答" aria-label="Permalink to &quot;149. 没有 MES、E-DHR 或 UniApp 实战经验，如何回答？&quot;">​</a></h3><p><strong>参考回答：</strong> 如实说明未交付的领域，再讲已有的可迁移能力，例如状态流转、库存并发、接口重试、权限和日志，并用本系列场景解释准备过的实现与验证方法。提出先理解现场流程、跟随现有规范完成一个小闭环的入手方式。</p><p><strong>可用表达：</strong> “我没有把准备案例当作交付经历，但能说明报工接口如何校验、如何防重和如何测试。领域规则会先与生产及质量人员确认，再落实到受控功能。”不要捏造项目规模、成果百分比或审计结论。</p><h3 id="_150-怎样用三分钟讲一个最符合这份-jd-的项目" tabindex="-1">150. 怎样用三分钟讲一个最符合这份 JD 的项目？ <a class="header-anchor" href="#_150-怎样用三分钟讲一个最符合这份-jd-的项目" aria-label="Permalink to &quot;150. 怎样用三分钟讲一个最符合这份 JD 的项目？&quot;">​</a></h3><p><strong>参考回答：</strong> 用真实项目说明业务目标、本人边界、技术方案、一次关键难题、验证和结果。技术内容围绕字段与流程、MySQL、权限、接口可靠性及上线支持展开，结果使用有依据的数量、耗时或缺陷变化，没有统计就描述可核查的交付事实。</p><p><strong>反问面试官：</strong> 可以询问现有 Laravel 与 MySQL 版本、核心系统职责、最大数据量、设备接入方式、当前故障痛点，以及质量验证和发布由谁批准。借此判断岗位更偏开发、集成还是现场运维。</p><h2 id="自测与复习安排" tabindex="-1">自测与复习安排 <a class="header-anchor" href="#自测与复习安排" aria-label="Permalink to &quot;自测与复习安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>复习轮次</th><th>内容</th><th>验收方式</th></tr></thead><tbody><tr><td>第一轮</td><td>01—50：PHP、Laravel、MySQL</td><td>能说清请求链路、事务、幂等、索引和扣料并发</td></tr><tr><td>第二轮</td><td>51—100：集成、设备、生产、电子记录</td><td>能画出数据链路，解释重复、乱序、补偿及记录更正</td></tr><tr><td>第三轮</td><td>101—125：UniApp 与移动端</td><td>能说明登录、扫码、离线队列、冲突和跨端限制</td></tr><tr><td>第四轮</td><td>126—150：验证、上线、协作</td><td>用真实项目完成一次故障排查题和三分钟项目介绍</td></tr></tbody></table><p>时间有限时，先看 <strong>10、13、15—18、29—30、35—43、55、59—67、76—79、87—94、107—119、127—128、134—140、149—150</strong>。每题先用自己的话回答，再对照参考内容检查遗漏；不要只背术语。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./uniapp-mobile-interview.html">上一篇：UniApp、小程序与 APP（101—125）</a></li><li><a href="./laravel-php-interview.html">从第一篇开始：Laravel 与后端开发（01—25）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="./../soft/requirement-translation.html">既有专题：技术沟通与需求转化</a></li></ul>',85)])])}const c=t(n,[["render",s]]);export{u as __pageData,c as default};
